var archiveItemTemplate = "";
var archiveTemplate = "";
var photoTemplate = "";
loadArchiveItemTemplate();

function build(type){
    console.log( "build page for type " + type );

    var articleData = myHelper.getArticles( type );
    if( null == articleData ){
        console.log("Can't find the data from database      <<<<<<< ")
        return "";
    }

    var resultPage = "";

    /*
    articleData[i][0] = ID
    articleData[i][1] = cateogry
    articleData[i][2] = year
    articleData[i][3] = month
    articleData[i][4] = day
    articleData[i][5] = title
    articleData[i][6] = detail
     */


    if( Object.keys(articleData).length == 0 ){
        console.log( "failed to load articles.");
        return "";
    }
    console.log( "data size : " + articleData.length);

    const count = articleData.length;
    if( myHelper.PHOTO_TYPE() == type ){
        console.log("start to build photo page now.");

        //resultPage = buildPhotoPage(articleData);
        resultPage = buildPhotoIndex(articleData);

        return resultPage;
    }

    var currentMonth = 0;

    var oneResult = "";
    var oneItem = "";

    //var idvalue = ARCHIVE_PAGE_BASE_ID;
    for( var i = 0; i<count; ++i){

        //console.log( "address row : " + articleData[i][0]  );

        if( currentMonth != articleData[i][3]){
            oneResult = oneResult.replace(archiveFillinItem, oneItem);
            resultPage += oneResult;
            oneItem = ""; //clear for next group
            currentMonth = articleData[i][3];

            var yearMonth = articleData[i][2] + " " + myHelper.getMonthShortName(articleData[i][3]);
            oneResult = archiveTemplate.replace(archiveFillinYearMonth, yearMonth);
        }

        var tempItem = archiveItemTemplate.replace(archiveItemID, articleData[i][0]);
        oneItem += tempItem.replace(archiveFillinTitle, articleData[i][5]);

    }
    oneResult = oneResult.replace(archiveFillinItem, oneItem);
    resultPage += oneResult;

    //console.log( "\r\nHome Screen is : " + homePageResult);
    console.log("exit build page");
    return resultPage;
}

function buildPhotoIndex( articleData ){
    console.log("enter buildPhotoIndex.");

    const count = articleData.length;
    //for( var i = 0; i<count; ++i){   each time, only build one page as client request
    var photoIndexResult ="";
    for( var i = 0; i<count; ++i){

        //console.log( "articleData[i][0] = " + articleData[i][0] );
        //console.log( "articleData[i][1] = " + articleData[i][1] );
        //console.log( "articleData[i][2] = " + articleData[i][2] );
        //console.log( "articleData[i][3] = " + articleData[i][3] );
        //console.log( "articleData[i][4] = " + articleData[i][4] );
        console.log( "articleData[i][5] = " + articleData[i][5] );
        //console.log( "articleData[i][6] = " + articleData[i][6] );

        const name_place_holder = "GROUP_NAME";
        const dataID_place_holder = "DATA_ID";
        const menuItemTempalte = "<option data='DATA_ID'>GROUP_NAME</option>";
        //const menuItemTempalte = "<li class='menu-li' data='DATA_ID'><div>GROUP_NAME<\/div><\/li>";
        const item = menuItemTempalte.replace( name_place_holder, articleData[i][5] );
        photoIndexResult += item.replace( dataID_place_holder, articleData[i][0] );

        console.log( "result i: " + photoIndexResult );
    }

    return photoIndexResult;
}

function buildPhotoPage2( articleData ){
    console.log("enter buildPhotoPage2.");

    const templateA = "<div class=\"ui-block-a photothumb\" id=\"PhotoID\" data=\"PHOTOX\" >PhotoSN</div>";
    const templateB = "<div class=\"ui-block-b photothumb\" id=\"PhotoID\" data=\"PHOTOX\" >PhotoSN</div>";
    const templateC = "<div class=\"ui-block-c photothumb\" id=\"PhotoID\" data=\"PHOTOX\" >PhotoSN</div>";
    const templates = [templateA, templateB, templateC];
    console.log("templates : " + templates );

    const photoNamePlaceholder = "PHOTOX";
    const photoIDPlaceHolder = "PhotoID";
    const photoIDPrefix = "Photo";
    const PhotoSNPlaceHolder = "PhotoSN";

    const count = articleData.length;
    //for( var i = 0; i<count; ++i){   each time, only build one page as client request
    var onePagePhotoResult ="";
    for( var i = 0; i<1; ++i){

        console.log( "articleData[i][0] = " + articleData[i][0] );
        console.log( "articleData[i][1] = " + articleData[i][1] );
        console.log( "articleData[i][2] = " + articleData[i][2] );
        console.log( "articleData[i][3] = " + articleData[i][3] );
        console.log( "articleData[i][4] = " + articleData[i][4] );
        console.log( "articleData[i][5] = " + articleData[i][5] );
        console.log( "articleData[i][6] = " + articleData[i][6] );

        var path = "./" + articleData[i][6];
        console.log( "readdir target: " + path);

        var photoNames = myHelper.getPhotoNames(path);
        console.log( "Photo count: " + photoNames.length );
        var photoCount = photoNames.length;
        for(var i = 0; i< photoCount; ++i){
            console.log("photo index : " + i );
            const index = i % 3;
            console.log( "index : " + index );
            var currentPage = templates[index ];
            console.log(photoNames[i]);
            currentPage = currentPage.replace( photoNamePlaceholder, path + "/" + photoNames[i] );
            currentPage = currentPage.replace( photoIDPlaceHolder, photoIDPrefix + i );
            currentPage = currentPage.replace( PhotoSNPlaceHolder, (i+1) + "." );
            console.log("current page : " +  currentPage );
            onePagePhotoResult += currentPage;
        }

        //console.log( "result 1: " + onePagePhotoResult );
    }

    //The following is async call which will NOT wait for fs.readdir abo
    const photosPlaceholder = "PlaceHolder";
    console.log( "result 2: " + onePagePhotoResult );
    return photoTemplate.replace( photosPlaceholder, onePagePhotoResult);
}

var  photoPage = "";
var experiencePage = "";
var androidPage = "";
var iOSPage = "";
var designPage = "";
var languagePage = "";
var toolPage = "";
var engineeringPage = "";
var newsPage = "";

exports.buildPage = function( type, data )
{
    console.log("buildPage : " + type );
    switch( type ){
        case myHelper.ALL_TYPES():
            //if( 0 == photoPage.length ){
                console.log( "build all archived pages");
                //var allArchivedPages = build(type);
            var allArchivedPages = build( ~myHelper.PHOTO_TYPE());
            //}
            return allArchivedPages;
            break;
        case myHelper.PHOTO_TYPE():
            if( 0 == photoPage.length ){
                console.log( "build photo page");
                photoPage = build(type); //this will build photo droplist menu, not actual photo.
            }
            return photoPage;
            break;
        case myHelper.PHOTO_PAGE_TYPE():  //this will build one particular photo page based on user selection from
                                            //droplist menu.
            console.log("want a photo page : " + data )

            return buildPhotoPage( data );
            break;
        case myHelper.EXPERIENCE_TYPE():
            if( 0 == experiencePage.length ){
                console.log( "build experience page");
                experiencePage = build(type);
            }
            return experiencePage;
            break;
        case myHelper.ANDROID_TYPE():
            if( 0 == androidPage.length ){
                console.log( "build android page");
                androidPage = build(type);
            }
            return androidPage;
            break;
        case myHelper.IOS_TYPE():
            if( 0 == iOSPage.length ){
                console.log( "build iOS page");
                iOSPage = build(type);
            }
            return iOSPage;
            break;
        case myHelper.DESIGN_TYPE():
            if( 0 == designPage.length ){
                console.log( "build design page");
                designPage = build(type);
            }
            return designPage;
            break;
        case myHelper.LANGUAGE_TYPE():
            if( 0 == languagePage.length ){
                console.log( "build language page");
                languagePage = build(type);
            }
            return languagePage;
            break;
        case myHelper.TOOLS_TYPE():
            if( 0 == toolPage.length ){
                console.log( "build tool page");
                toolPage = build(type);
            }
            return toolPage;
            break;
        case myHelper.ENGINEERING_TYPE():
            if( 0 == engineeringPage.length ){
                console.log( "build engineering page");
                engineeringPage = build(type);
            }
            return engineeringPage;
            break;
        case myHelper.NEWS_TYPE():
            if( 0 == newsPage.length ){
                console.log( "build news page");
                newsPage = build(type);
            }
            return newsPage;
            break;
        default:
            console.log("unsupported build type : " + type );
    }

    //return empty string if unknown build type is input.
    return "";
}